// F唯一两根/固定tag，RES3只是引用原Common型别，不复制holder注册或给未知owner默认权限。
#pragma once
#include "model.hpp"
#include "resident/kernel/exact_struct_codec.hpp"
#include <limits>
namespace hanmo::resident::facility_fields {
using namespace exact_fields;
template<class C> Status slot(C& c,FacilitySlotRef& v){required_ref(c,"provider_domain",v.provider_domain);required_ref(c,"facility_id",v.facility_id);return required_ref(c,"slot_kind",v.slot_kind);}
template<class C> Status source_ref(C& c,FacilitySourceRef& v){c.object("source_ref",[&](auto& x){return source(x,v.source_ref);});return schema(c,"source_schema",v.source_schema);}
template<class C> Status receipt_ref(C& c,FacilityClaimReceiptRef& v){c.object("slot_ref",[&](auto& x){return slot(x,v.slot_ref);});c.field("claim_set_revision",v.claim_set_revision);if(c.status().ok&&v.claim_set_revision<=0)return c.reject("InvalidFacilityClaimReceiptRef");return c.status();}
template<class C> Status holder(C& c,ReservationRef& v){Integer kind=static_cast<Integer>(v.kind);finite(c,"kind",kind,3);required_ref(c,"id",v.id);if(c.status().ok&&c.reading())v.kind=static_cast<ReservationRef::Kind>(kind);if(kind==3){required_ref(c,"domain_id",v.domain_id);required_ref(c,"activity_kind",v.activity_kind);}else if(c.reading()){v.domain_id.clear();v.activity_kind.clear();}else if(!v.domain_id.empty()||!v.activity_kind.empty())return c.reject("UnexpectedLegacyReservationDomain");return c.status();}
template<class C> Status claim(C& c,FacilityClaim2& v){required_ref(c,"claim_id",v.claim_id);c.object("slot_ref",[&](auto& x){return slot(x,v.slot_ref);});c.object("holder",[&](auto& x){return holder(x,v.holder);});c.object("from",[&](auto& x){return moment(x,v.from);});c.object("until",[&](auto& x){return moment(x,v.until);});c.field("units",v.units);c.field("capacity_revision",v.capacity_revision);c.object("usage_right_ref",[&](auto& x){return source(x,v.usage_right_ref);});c.object("source_result_ref",[&](auto& x){return source(x,v.source_result_ref);});if(c.status().ok&&(v.units<=0||v.capacity_revision<=0||v.from.half_day_tick<0||take(compare_world_moments(v.from,v.until))>=0))return c.reject("InvalidFacilityClaimValue");return c.status();}
template<class C> Status mutation(C& c,FacilityClaimMutationReceipt& v){c.field("claim_set_revision",v.claim_set_revision);c.object("occurred_at",[&](auto& x){return moment(x,v.occurred_at);});c.object("source_result_ref",[&](auto& x){return source(x,v.source_result_ref);});schema(c,"source_schema",v.source_schema);const StableId* previous=nullptr;c.sequence("closed_claims",v.closed_claims,[&](auto& x,auto& close){required_ref(x,"claim_id",close.claim_id);Integer reason=static_cast<Integer>(close.reason);finite(x,"reason",reason,7);if(x.status().ok&&x.reading())close.reason=static_cast<FacilityClaimCloseReason>(reason);if(x.status().ok&&previous&&close.claim_id<=*previous)return x.reject("InvalidFacilityCloseOrder");previous=&close.claim_id;return x.status();});std::size_t position=0;c.sequence("admitted_claims",v.admitted_claims,[&](auto& x,auto& row){auto s=claim(x,row);if(s.ok)for(std::size_t i=0;i<position;++i)if(v.admitted_claims[i].claim_id==row.claim_id)return x.reject("DuplicateFacilityClaimAdmission");++position;return s;});c.sequence("capacity_source_refs",v.capacity_source_refs,[](auto& x,auto& row){return source_ref(x,row);});if(c.status().ok&&v.claim_set_revision<=0)return c.reject("InvalidFacilityMutationRevision");return c.status();}
template<class C> Status base(C& c,FacilityHistoryBase& v){Integer tag=v.index();finite(c,"tag",tag,1);if(!c.status().ok)return c.status();if(c.reading()){if(tag==0)v=InitialEmptyFacilityClaims{};else v=VacantPrunedFacilityPrefix{};}if(tag==1){auto& x=std::get<VacantPrunedFacilityPrefix>(v);c.field("last_removed_revision",x.last_removed_revision);c.object("cut_at",[&](auto& z){return moment(z,x.cut_at);});c.object("last_close_result_ref",[&](auto& z){return source(z,x.last_close_result_ref);});schema(c,"last_close_source_schema",x.last_close_source_schema);if(c.status().ok&&x.last_removed_revision<=0)return c.reject("InvalidFacilityPrunedPrefix");}return c.status();}
template<class C> Status history(C& c,FacilitySlotHistory& v){c.object("slot_ref",[&](auto& x){return slot(x,v.slot_ref);});c.object("base",[&](auto& x){return base(x,v.base);});Integer revision=0;if(auto* prefix=std::get_if<VacantPrunedFacilityPrefix>(&v.base))revision=prefix->last_removed_revision;const WorldMoment* previous=nullptr;c.sequence("mutations",v.mutations,[&](auto& x,auto& row){auto s=mutation(x,row);if(!s.ok)return s;if(revision==std::numeric_limits<Integer>::max()||row.claim_set_revision!=revision+1||(previous&&take(compare_world_moments(*previous,row.occurred_at))>0))return x.reject("InvalidFacilityHistoryChain");revision=row.claim_set_revision;previous=&row.occurred_at;return x.status();});return c.status();}
template<class C> Status state(C& c,FacilityClaimsState& v){std::size_t position=0;c.sequence("claims",v.claims,[&](auto& x,auto& row){auto s=claim(x,row);if(s.ok)for(std::size_t i=0;i<position;++i)if(v.claims[i].claim_id==row.claim_id)return x.reject("DuplicateActiveFacilityClaim");++position;return s;});const FacilitySlotRef* prior=nullptr;c.sequence("slot_histories",v.slot_histories,[&](auto& x,auto& row){auto s=history(x,row);if(s.ok&&prior&&!(*prior<row.slot_ref))return x.reject("InvalidFacilityHistorySlotOrder");prior=&row.slot_ref;return s;});return c.status();}
template<class C> Status catalog(C& c,FacilityClaimsCatalog& v){c.field("max_claim_half_days",v.max_claim_half_days);std::size_t position=0;c.sequence("selected_slots",v.selected_slots,[&](auto& x,auto& row){auto s=slot(x,row);if(s.ok)for(std::size_t i=0;i<position;++i)if(v.selected_slots[i]==row)return x.reject("DuplicateSelectedFacilitySlot");++position;return s;});if(c.status().ok&&(v.max_claim_half_days<=0||v.max_claim_half_days==std::numeric_limits<Integer>::max()))return c.reject("InvalidFacilityClaimWindowPolicy");return c.status();}
}
